import {SKILLS,ITEMS,CLASSES} from './data-v14.js';
import {V11_ECONOMY} from './combat-data-v14.js';
import {enchantPrice} from './chapter4-runtime-v14.js';
import {enchantDescription,ENCHANT_DEFS,ENCHANT_RULES} from './enchantments-v14.js';
export const forgeUI={gearId:null,family:'all'};
const slots={weapon:'武器',head:'头部',chest:'上衣',hands:'护手',feet:'靴子',relic:'遗物'};
export function v11FacilityHTML(g,kind,{iconHTML,miniItemIcon,skillDetails,escape,gearIcon}){
 const shell=(title,body)=>`<div class="modal"><section class="panel"><header class="panel-head"><div><small>旅途中的修行</small><h2>${title}</h2></div><button data-act="resume">返回 ×</button></header><div class="panel-body">${body}</div></section></div>`;
 const h=g.v11,p=g.p;if(kind==='teaching')return shell('向艾莉娅请教',`<p>她会的圣光技法与路上读书学到的招式，都可以请教。学会后从一阶开始，再用诺恩自己的技能点提升。已有等级不会改变。</p><div class="teaching-grid">${g.teachableSkills().map(k=>`<article class="teaching-card"><div class="skill-heading">${iconHTML(k)}<h3>${SKILLS[k].name}</h3></div><p>${SKILLS[k].desc}</p>${skillDetails(k)}<button data-v11="teach" data-arg="${k}" ${p.skills[k]?'disabled':''}>${p.skills[k]?'已掌握 · '+p.skills[k]+' 阶':'请教这项技法 · 免费'}</button></article>`).join('')}</div><p class="tip">传授不自动更换激活技能或快捷栏。最多同时激活五种。</p>`);
 if(kind==='roadReward')return shell('车里留下的练习页',h.roadReward?`<p>芮妲从旧工人的行囊里翻出三本册子。选一本先带在身边，另外的留给来往的人。</p><div class="teaching-grid">${['boneBreakBook','emberLanceBook','ashWardBook'].map(k=>`<article class="teaching-card"><h3>${ITEMS[k].name}</h3><p>${ITEMS[k].desc}</p>${skillDetails(ITEMS[k].skill)}<button data-v11="roadReward" data-arg="${k}">收下这本</button></article>`).join('')}</div>`:'<p>你选的那份已经收在行囊里。读过后，可以在技能页调整。</p>');
 if(kind==='shop')return shell('薇塔的药箱',`<p>金币 <b>${p.gold}</b>　疗伤药 ${p.items.hp||0}　清醒药 ${p.items.mp||0}</p><div class="teaching-grid">${V11_ECONOMY.shop.map((s,i)=>`<article class="teaching-card">${miniItemIcon(s.item)}<h3>${ITEMS[s.item].name} × ${s.bundle}</h3><p>${ITEMS[s.item].desc}</p><button data-v11="buy" data-arg="${i}" ${p.gold<s.price?'disabled':''}>购买 · ${s.price} 金</button></article>`).join('')}</div><p class="tip">营地炉边也可以休息，恢复全部生命与法力，25 金。</p>`);
 const gear=[...Object.values(p.gear).filter(Boolean),...p.bag],offer=h.pendingEnchant;
 let target=gear.find(i=>i.id===(offer?.gearId||forgeUI.gearId));if(!target)target=gear[0];if(target)forgeUI.gearId=target.id;
 const price=enchantPrice(g),enough=Object.entries(price).every(([k,n])=>(k==='gold'?p.gold:p.items[k]||0)>=n),cost=Object.entries(price).filter(([,n])=>n).map(([k,n])=>`${k==='gold'?'金币':ITEMS[k].name} ${n}`).join(' + '),pool=target?Object.values(ENCHANT_DEFS).filter(d=>d.slots.includes(target.slot)&&(forgeUI.family==='all'||d.kind===forgeUI.family)):[];
 return shell('赫伦的刻魂锻台',`<p>每件装备可以留下一道刻印。重新刻印会给出新结果，可采用它，或保留旧刻印；原本的装备属性和独特特性保留。</p><div class="summary"><span>金币 <b>${p.gold}</b></span><span>烬晶砂 <b>${p.items.ashGlass||0}</b></span><span>魂灰 <b>${p.items.soulAsh||0}</b></span></div><div class="enchant-workspace"><section><h3>选择身上或行囊中的装备</h3><div class="inventory-grid">${gear.map(i=>`<button class="inventory-cell ${i.rarity} ${i.id===target?.id?'chosen':''}" data-forge-gear="${escape(i.id)}" ${offer?'disabled':''} aria-label="刻印${escape(i.name)}" title="${escape(i.name)}">${gearIcon(i)}</button>`).join('')}</div></section><section class="selected-detail">${target?`<div class="item-heading">${gearIcon(target)}<div><small>${slots[target.slot]}</small><h3>${escape(target.name)}</h3></div></div><p>原装备：攻击 +${target.atk} / 生命 +${target.hp}${target.attrs?' / '+Object.entries(target.attrs).map(([k,v])=>`${{str:'力量',dex:'敏捷',vit:'体质',wis:'精神'}[k]} +${v}`).join(' · '):''}</p><article class="enchant-old"><small>当前刻印</small><p>${enchantDescription(target.enchantment)}</p></article>${offer?`<article class="enchant-new"><small>待选刻印 · 本次材料已支付</small><p>${enchantDescription(offer.result)}</p></article><div class="row"><button class="primary" data-v11="adopt">采用新刻印</button><button data-v11="keep">保留原刻印</button></div><p class="tip">关闭后仍保留这份结果，决定后才能再次刻印。保留原刻印也不退回材料。</p>`:`<nav class="bag-categories">${Object.entries({all:'不限类型',stat:'属性刻印',element:'武器附伤',skill:'技能变化'}).map(([k,n])=>`<button data-forge-family="${k}" class="${forgeUI.family===k?'on':''}">${n}</button>`).join('')}</nav><p>${h.tutorialUsed?'本次所需':'第一次试作'}：${cost}</p><button class="primary" data-v11="enchant" data-arg="${escape(target.id)}" data-arg2="${forgeUI.family}" ${!enough||!pool.length?'disabled':''}>刻下一道新纹</button><p class="muted">品质：微光70% · 清晰26% · 炽明4%。部位与类型决定可出现的刻印，数值在该品质范围内随机。</p><details><summary>本部位可出现的刻印（${pool.length}）</summary>${pool.map(d=>`<p><b>${d.name}</b> · ${d.display.replaceAll('{value}',`${d.range.common[0]}–${d.range.epic[1]}`).replaceAll('{decimal}',`${d.range.common[0]/10}–${d.range.epic[1]/10}`)}</p>`).join('')}</details><p class="tip">生成结果时扣费。技能刻印不会直接教会招式，学会对应技能后才生效。</p>`}`:'<p>先从行囊带一件装备过来。</p>'}</section></div>`);
}
